    "# HỒ SƠ KHUNG STORY BIBLE — THỂ LOẠI TRINH THÁM NOIR / BÍ ẨN": "# 设定集结构框架 (STORY BIBLE) — 黑色侦探 / 悬疑推理题材",
    "- Bối cảnh trung tâm: Tháp Đồng Hồ Đêm Mưa & Thành phố Cảng Sương Mù.": "- 核心场景：雨夜钟楼与迷雾港城。",
    "- Quy luật thời gian: Chuông đồng chỉ rung khi có sự cố chuyển giao ký ức hoặc mở khóa tầng áp mái.": "- 时间铁律：唯有发生记忆同步异变或开启阁楼密室时，青铜钟才会鸣响。",
    "- Giọng văn chủ đạo: Noir tiết chế, giàu chi tiết giác quan (mưa, đồng thau, giấy da, ánh đèn bão).": "- 主导文风：克制冷峻的黑色推理风，富含感官细节（冷雨、黄铜、旧羊皮纸、风灯微光）。",
    "=== TỔNG HỢP STORY BIBLE CHÍNH THỨC (BẢN MẪU GUEST MODE) ===": "=== 官方设定集汇总（访客模式示例工程） ===",
    "1. Bối cảnh & Luật ngầm:": "1. 背景设定与潜规则：",
    "- Vụ hỏa hoạn 20 năm trước thực chất là màn che đậy cho cuộc thử nghiệm lưu trữ ký ức của Giáo sư Hoàng tại Tháp Đồng Hồ.": "- 20 年前的大火实际上是为了掩盖黄教授在钟楼进行的记忆封存实验。",
    "- Con số 13:00 trên mặt đồng hồ không chỉ thời gian mà là mã khóa cơ học nối lên gác chuông.": "- 钟面上的 13:00 并非火灾时间，而是通往顶层钟楼的机械密码。",
    "2. Tuyến nhân vật chính:": "2. 核心角色阵营：",
    "- Trần Minh Khôi (Chính): Thám tử lưu trữ, có vết sẹo cũ ở cổ tay trái, luôn giữ đồng hồ quả quýt vỡ kính.": "- 陈明魁（主角）：档案调查员，左腕留有旧疤，随身带着表面碎裂的怀表。",
    "- Lệ Băng (Đồng hành / Nghi phạm): Người giữ chùm chìa khóa đồng La Mã, nắm nửa sự thật về vụ hỏa hoạn.": "- 丽冰（搭档 / 嫌疑人）：罗马数字青铜钥匙串的守门人，掌握着当年火灾的一半真相。",
    "- Bé Miu (Nhân chứng bí ẩn): Xuất hiện trong hầm kín dù cửa khóa ngoài, cầm mảnh đồng khắc tên Giáo sư Hoàng.": "- 小喵（神秘目击者）：在大门反锁的地下室神秘现身，手中握有刻着黄教授名字的铜片。",
    "- Giáo sư Hoàng (Phản diện giấu mặt): Tác giả chuỗi sổ cái bìa đen và cỗ máy đồng bộ xung chuông.": "- 黄教授（幕后反派）：六本黑皮账册与钟声脉冲记忆同步装置的缔造者。",
    "3. Mạch phục bút đang chạy:": "3. 正在推进的伏笔脉络：",
    "- Chìa khóa thứ tư hình bán nguyệt úp ngược -> Mở két sắt tầng áp mái.": "- 刻有倒置半月纹的第四把钥匙 -> 开启阁楼保险箱。",
    "- Vết thương cổ tay trái của Minh Khôi cộng hưởng với tần số chuông đồng.": "- 明魁左腕的旧伤与青铜大钟的震动频率产生共鸣。",
    "Nhân vật chính (Thám tử lưu trữ)": "主角（档案调查侦探）",
    "Điềm tĩnh, quan sát tỉ mỉ chi tiết cơ học, ám ảnh công lý bị chôn vùi.": "沉着冷静，细致观察机械构造细节，执着于追查被掩埋的正义。",
    "Ngắn gọn, sắc bén, dùng ngôi \"Tôi\" — gọi Lệ Băng bằng chức danh hoặc tên.": "简短锋利，自称“我”——直呼丽冰其名或职务。",
    "Người giữ khóa Tháp Đồng Hồ": "钟楼守钥人",
    "Lạnh lùng bên ngoài nhưng cố bảo vệ bằng chứng gốc trước thế lực giấu mặt.": "外表冷漠，实则暗中守护原始证据以免落入幕后黑手。",
    "Mỉa mai nhẹ, hay đặt câu hỏi ngược để dò thái độ.": "略带冷嘲，习惯用反问句试探对方立场。",
    "Nhân chứng bí ẩn": "神秘目击者",
    "Nhạy bén với âm thanh bánh răng, xuất hiện tại những nơi tưởng chừng kín bưng.": "对齿轮声极其敏锐，常在看似密闭的场所神秘现身。",
    "Ngây thơ nhưng câu nào cũng chứa ẩn ý cảnh báo.": "语气天真无邪，但每句话都暗藏警示深意。",
    "Phản diện giấu mặt": "幕后隐藏反派",
