    "Trang trọng, học thuật qua các trang sổ cái để lại.": "留存账册中的文风庄重严谨、充满学术气息。",
    "13:00 là mã khóa gác chuông chứ không phải giờ cháy": "13:00 是顶层钟楼的机械密码而非起火时间",
