    "Trùng khớp mảnh giấy cháy dở tại viện lưu trữ, dùng mở két tầng áp mái.": "与档案馆拾获的半焦残纸完全吻合，用于开启阁楼保险箱。",
    "Con búp bê thiếu một chiếc cúc mắt & mảnh đồng tên Giáo sư Hoàng": "缺了一颗纽扣眼睛的布偶与刻有黄教授名字的铜片",
