    "“Ánh đèn huỳnh quang nhấp nháy cắt ngang sống mũi hắn, hắt một vệt bóng xám dài xuống mặt bàn gỗ.”": "“闪烁的日光灯光线斜切过他的鼻梁，在木桌面上投下一道长长的灰影。”",
