    "“Đầu ngón tay đang giữ quai tách khẽ khựng lại, làm gợn sóng nhỏ trong lòng chén trà sậm màu.”": "“握着茶杯柄的指尖微微一顿，在深色茶汤中荡起一圈细小的涟漪。”",
    "Cô độc / Lạnh lẽo đô thị": "孤独 / 都市冷清",
    "“Ánh neon từ biển hiệu đối diện rỉ qua khe rèm chớp, nhuộm xanh bệ cửa sổ ẩm sương.”": "“对面招牌的霓虹灯透过百叶窗缝隙渗入，将沾满潮气的窗台染成一片幽蓝。”",
    "Ngỡ ngàng sững sờ": "错愕呆滞",
    "“Đồng tử mở to hơn bình thường một chút, phản chiếu nguyên vẹn ngọn lửa nhỏ đang rung trước gió.”": "“瞳孔比平常微微放大了一分，完整倒映出风中摇曳的微弱火苗。”",
    "Kiệt sức sau biến cố": "变故后的疲惫",
    "“Quầng thâm mờ dưới mi mắt khiến cái chớp mắt của cô chậm hơn bình thường nửa nhịp.”": "“眼睑下淡淡的青黑，让她每次眨眼都比平时慢了半拍。”",
    "Cảnh giác tột độ": "高度警觉",
    "“Ánh nhìn quét nhanh qua khe cửa khép hờ, dừng đúng hai giây ở vệt bùn mới in cạnh thảm chùi chân.”": "“视线迅速扫过虚掩的门缝，在门垫旁新印上的泥痕上恰恰停留了两秒。”",
    "🌦️ Bối Cảnh Thời Tiết & Ánh Sáng Điện Ảnh (Chèn Nhanh Mở Cảnh)": "🌦️ 电影感天气与光影背景（快速插入开场）",
    "🌧️ Mưa đêm & Đèn đường": "🌧️ 夜雨与路灯",
    "Chèn mở cảnh": "插入开场描写",
    "Hạt mưa đập chéo vào mặt kính quán cà phê, kéo nhòe vệt đèn hậu đỏ rực bên kia đại lộ.": "雨点斜打在咖啡馆玻璃窗上，把大道对岸鲜红的车尾灯拉成模糊的光痕。",
    "🌫️ Sương sớm vùng cao / Đà Lạt": "🌫️ 高原晨雾 / 大叻",
    "Lớp sương trắng bàng bạc vắt ngang hàng thông, thấm lạnh qua gấu áo len ngay khi cửa vừa hé.": "一层银白色的晨雾横亘在松林间，门刚推开一条缝，寒意便透过毛衣下摆渗了进来。",
    "☀️ Trưa nắng gắt ngột ngạt": "☀️ 闷热毒辣的午后艳阳",
    "Mặt đường nhựa bốc hơi nóng hập hừ, ánh nắng chói chang khiến bóng đổ dưới chân co rút thành một chấm đen sắc lẹm.": "柏油路面蒸腾着灼人的热浪，刺眼的烈日将脚下的影子缩成一团锐利的黑点。",
    "🌃 Đêm mất điện / Ánh nến": "🌃 停电之夜 / 烛光摇曳",
    "Bóng trần nhà rung rinh theo ngọn bấc đèn cầy mỗi lần có luồng gió lùa qua khe cửa gỗ mục.": "每当穿堂风从腐朽木门的缝隙钻入，天花板上的影子便随着烛芯一同晃动。",
    "🍂 Gió thu cuối chiều": "🍂 傍晚微凉的秋风",
    "Cơn gió se sắt cuốn theo mùi hoa sữa hăng hắc và tiếng lá khô lạo xạo lăn qua bậc thềm đá.": "微寒的秋风卷来糖胶树花略带辛涩的香气，以及枯叶滚过石阶的沙沙声。",
