    "CỔNG KẾT NỐI · TẢI APP PWA · MOD 01-05 · MOD 29-30": "连接入口 · PWA 应用下载 · MOD 01-05 · MOD 29-30",
    "🇻🇳 Chào mừng bạn tới Bi's Novel Writing Studio với bộ biểu tượng chân dung mới! Ngay đầu cổng là nút Mai Hải Đăng (Bi), nút to Ủng hộ Đăng và nút Tải App về thiết bị ngay.": "🇻🇳 欢迎来到全新头像图标版 Bi 小说创作工坊！入口最上方设有 Mai Hải Đăng (Bi) 按钮、醒目的支持 Đăng 按钮以及立即下载应用到设备的按钮。",
