    "\"Mình lấy cảm hứng từ nỗi đau không có web riêng, mình thì không biết lập trình nên là mình làm hơi lâu, cụ thể là 3 ngày với AI, mong mọi người thông cảm nếu có sai sót nha, có gì cứ report bug cho m": "“我的灵感源于没有专属写作网页的痛点。因为不懂编程，做起来稍微久了点，具体来说是和 AI 一起花了 3 天时间。若有疏漏之处还请大家多多包涵，有什么问题欢迎随时向我反馈 Bug！”",
    "Giải nghĩa nhỏ:": "小科普：",
    "Góc nhỏ giải nghĩa tên gọi: \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng, vì vậy đứa con tinh thần này mới mang cái tên gần gũi là \"Bi's Novel Writing Studio\".": "名字由来小贴士：「Bi」正是作者 Mai Hải Đăng 在家里的亲切小名，因此这份心血之作才取名为「Bi 小说创作工坊」。",
