    "· Tạo dựng bằng 3 ngày toàn tâm cùng AI": "· 与 AI 全心共创 3 天打造",
    "Chúc bạn luôn giữ được ngọn lửa cảm hứng cho từng chương truyện!": "愿你为每一章故事永远保持炽热的创作灵感！",
    "📚 Nhật Ký 3 Ngày Chế Tác Web": "📚 3 天建站日志",
