    "Bạn đã gõ những con chữ đầu tiên trong Studio. Mọi đại tiểu thuyết đều bắt đầu từ dòng chữ thứ nhất.": "你已在工坊中敲下最初的文字。每一部伟大长篇都始于第一行。",
