    "Vượt mốc 10.000 từ với 3 chương hoàn chỉnh — tương đương hồi mở màn của một bộ Light Novel thực thụ.": "突破 10,000 字并完成 3 个完整章节 — 相当于一部真正轻小说的开篇篇幅。",
    "Yêu cầu: 10,000 từ · 3 chương đã duyệt": "要求：10,000 字 · 3 已审核章节",
