    "Trên 30.000 từ — lúc này Story Bible, Ma trận Ai Biết Gì và Phục bút đã phát huy tối đa uy lực.": "超过 30,000 字 — 此时设定集、信息差矩阵与伏笔已发挥出最大威力。",
    "Yêu cầu: 30,000 từ · 6 chương đã duyệt": "要求：30,000 字 · 6 已审核章节",
