    "Đạt dung lượng 1 quyển Light Novel hoàn chỉnh! Hãy dùng Tab 6 xuất sách DOCX / PDF lưu giữ thành quả.": "已达一整卷完整轻小说的体量！快用 Tab 6 导出 DOCX / PDF 留存这份成果吧。",
    "Yêu cầu: 60,000 từ · 10 chương đã duyệt": "要求：60,000 字 · 10 已审核章节",
    "🌌 Đại Tự Sự Vượt Mọi Giới Hạn": "🌌 超越极限的宏大叙事",
    "Hơn 120.000 từ — Mai Hải Đăng xin gửi lời chúc mừng nồng nhiệt nhất tới sự kiên trì phi thường của bạn!": "突破 120,000 字 — Mai Hải Đăng 向你非凡的毅力致以最热烈的祝贺！",
    "Yêu cầu: 120,000 từ · 20 chương đã duyệt": "要求：120,000 字 · 20 已审核章节",
