    "Sao chép địa chỉ Gmail tác giả": "复制作者 Gmail 地址",
    "Mở trang Facebook chính thức của Mai Hải Đăng": "打开 Mai Hải Đăng 的官方 Facebook 主页",
    "Gửi một lời cảm ơn động viên tới tác giả": "向作者发送鼓励与感谢",
