    "Bảng ghi công tác giả tự động chạy từ trên xuống": "自动从上向下滚动的作者致谢字幕",
    "📚 Nhật Ký 3 Ngày Chế Tác Web Cùng AI — Author: Mai Hải Đăng": "📚 与 AI 携手 3 天建站日志 — 作者：Mai Hải Đăng",
    "Toàn bộ kiến trúc, giao diện, lập trình và kiểm thử đều do một mình tác giả Mai Hải Đăng thực hiện cùng AI.": "全部架构、界面设计、编程实现与测试均由作者 Mai Hải Đăng 独自与 AI 协同完成。",
    "✕ Đóng nhật ký": "✕ 关闭日志",
    "Tất cả (6)": "全部 (6)",
    "v38.5 · Ổn định": "v38.5 · 稳定版",
    "Ngày thứ 3 · Đêm hoàn thiện chuẩn Google Engineer": "第 3 天 · Google 工程师标准打磨之夜",
    "Thanh lọc văn phong AI thuần khiết, Cố vấn Mode 1 -> Mode 2 & Bộ 3 Module 34-35-36": "净化纯粹 AI 文风、Mode 1 -> Mode 2 顾问及 Module 34-35-36 三件套",
    "Đưa nút Approve & Lock Draft sang bên trái thanh Tab 2 và chống chồng chữ tuyệt đối ở mọi độ rộng.": "将 Approve & Lock Draft 按钮移至 Tab 2 工具栏左侧，并在所有屏幕宽度下彻底杜绝文字重叠。",
    "Sửa bộ lọc chương Tab 2: bấm Nháp chỉ hiện Nháp, bấm Đã duyệt chỉ hiện Đã duyệt, bấm Tổng mới hiện tất cả.": "修复 Tab 2 章节筛选：点「草稿」仅显示草稿，点「已审核」仅显示已审核，点「全部」才显示所有章节。",
    "Xây dựng Bộ 5 Prompt mẫu chuyên sâu với thanh chỉ dẫn xám riêng cho từng Chế độ (Mode 2 mở đầu bằng dàn ý thô).": "构建 5 套深度模板指令，各模式配备专属灰色引导栏（Mode 2 以粗略大纲开篇）。",
    "Khi chạy Mode 1 mà Mode 2 chưa có gợi ý diễn biến, bật nhắc thân thiện với cụm \"Mode 2\" gạch chân bấm nhảy thẳng sang Mode 2.": "当运行 Mode 1 而 Mode 2 尚无剧情推进建议时，弹出友好提示并提供带下划线的「Mode 2」点击直达跳转。",
    "Tự động dệt kết quả Mode 2 vào Prompt tổng hợp của Mode 1 để nối mạch truyện liền lạc.": "自动将 Mode 2 的输出编织进 Mode 1 综合指令中，确保剧情脉络无缝衔接。",
    "Cấm AI dùng ký tự thô (**, *, #, ---) trong 5 chế độ + Chatbot Bi, đồng thời lọc sạch văn bản đầu ra.": "禁止 AI 在 5 大模式及 Bi 聊天机器人中使用粗糙符号（**、*、#、---），并自动净化输出文本。",
    "Khử nền trắng chói cho toàn bộ hộp chọn <select> ở Tab 5 sang chữ trắng trên nền tối #09090b.": "消除 Tab 5 所有 <select> 下拉框的刺眼白底，统一改为 #09090b 深色背景配白色文字。",
    "Ra mắt Mod 34 (Báo lỗi người dùng), Mod 35 (Author Credits Mai Hải Đăng) và Mod 36 (Khiên Chống Reload mất chữ).": "推出 Mod 34（用户报错）、Mod 35（Mai Hải Đăng 作者致谢）及 Mod 36（防刷新防丢稿护盾）。",
    "Phạm vi:": "范围：",
    "🧭 4 Nguyên Tắc Cầm Tay Khi Mai Hải Đăng Xây Studio Này": "🧭 Mai Hải Đăng 构建本工坊时恪守的 4 项核心原则",
    "✍️ Người xây dựng duy nhất:": "✍️ 唯一开发者：",
    "Tìm tính năng hoặc module (vd: Tab 2, NotebookLM, Mod 36)...": "搜索功能或模块（如：Tab 2、NotebookLM、Mod 36）……",
    "💡 Chức năng này để giúp bạn đồng bộ trạng thái trang web và mọi công việc qua thiết bị khác thông qua tải file về máy sau đó bạn tự lấy máy khác tải về gói dữ liệu hoặc bạn kết nối tự động qua Google": "💡 此功能可将网页状态与全部创作进度同步至其他设备：您可以先将数据包下载到本地再传到另一台设备导入，或直接通过 Google Drive 自动连接同步。",
    "🗂️ Bước 1: Đặt Tên Thư Mục Kết Quả Làm Việc": "🗂️ 第 1 步：命名工作成果文件夹",
    "Tên này sẽ được dùng để đặt tên file .ZIP khi tải về máy và tên Thư mục tạo trực tiếp trên Google Drive của bạn.": "此名称将用作下载到本地的 .ZIP 文件名，以及直接在您的 Google Drive 上创建的文件夹名称。",
