    "Tạo ngay thư mục chứa toàn bộ chương, Story Bible và gói .ZIP trên Google Drive cá nhân, kèm tùy chọn mở link chia sẻ nhanh.": "立即在个人 Google Drive 中创建包含全部章节、设定集与 .ZIP 压缩包的文件夹，并附带一键开启链接共享选项。",
    "▾ Hướng Dẫn Tạo Key & Client ID": "▾ 创建 API Key 与 Client ID 指南",
    "Tạo hoặc chọn một Project trên Google Cloud Console rồi nhấn Enable (Bật) cho Google Drive API để trình duyệt được phép tạo thư mục và tải tệp.": "在 Google Cloud Console 中创建或选择一个 Project，然后为 Google Drive API 点击 Enable（启用），以允许浏览器创建文件夹并上传文件。",
    "Mở trang Bật Google Drive API ↗": "打开启用 Google Drive API 页面 ↗",
    "Vào Credentials → Create Credentials → API Key. Bạn có thể dán Key vào ô bên dưới rồi bấm \"Xác thực Key\" để kiểm tra kết nối Drive + Gemini Flash-Lite.": "进入 Credentials → Create Credentials → API Key。您可以将密钥粘贴到下方输入框，然后点击「验证密钥」测试 Drive 与 Gemini Flash-Lite 连接。",
    "Mở trang Credentials tạo API Key ↗": "打开 Credentials 创建 API Key ↗",
    "Tại mục Credentials → Create Credentials → OAuth client ID → chọn Application type là Web application. Dán đúng Origin hiện tại (sao chép ở nút bên dưới) vào mục Authorized JavaScript origins.": "在 Credentials → Create Credentials → OAuth client ID 中选择 Application type 为 Web application。将当前 Origin（通过下方按钮复制）准确粘贴至 Authorized JavaScript origins。",
    "Mở OAuth Consent / Client ID ↗": "打开 OAuth 同意屏幕 / Client ID ↗",
    "Nhấn \"Đăng nhập Google (drive.file)\" — Studio chỉ xin quyền truy cập các tệp/thư mục do chính Studio vừa tạo, tuyệt đối không đọc tệp riêng tư khác trong Drive của bạn.": "点击「使用 Google 登录 (drive.file)」— 工坊仅请求访问由工坊自身创建的文件/文件夹，绝不读取您 Drive 中的其他私密文件。",
