    "giúp giảm tối đa giao diện gây phân tâm xung quanh (cột bình luận, đề xuất). Lưu ý nếu chủ kênh YouTube khóa quyền nhúng bên thứ 3 hoặc bạn mở web trực tiếp bằng giao thức": "播放视频，最大限度减少周边干扰界面（评论区、推荐视频）。请注意，若 YouTube 频道主禁用了第三方嵌入权限，或您直接通过",
