    "Chặn tự gõ câu lệnh mới; chỉ cần bấm chọn Prompt mẫu là xem trọn quy trình tổng hợp Prompt, Google Docs Diff, Đánh giá độc giả và Biểu đồ SVG Mode 5.": "已禁用手动输入新指令；只需点击示例 Prompt，即可查看完整的 Prompt 合成流程、Google Docs Diff、读者评价及 Mode 5 SVG 图表。",
