    "💡 Vì sao là \"Web Viết Tiểu Thuyết Của Bi\"? Tên gọi \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng — đặt tên như vậy để góc sáng tác luôn giữ cảm giác gần gũi như ở nhà mình vậy.": "💡 为什么叫“Bi 小说创作工坊”？“Bi”正是作者 Mai Hải Đăng 在家里的亲切昵称 —— 这样命名，是希望这个创作角落永远保留像家一样亲切温暖的氛围。",
