    "Tab 6 (Xuất & Kho)": "Tab 6（导出与归档库）",
    "Thanh nổi & Bi #8": "悬浮条与 Bi #8",
    "▾ Cổng Xác Thực Gemini API Key Qua Flash-Lite & Link AI Studio 1-Click": "▾ 通过 Flash-Lite 验证 Gemini API Key 及一键跳转 AI Studio 入口",
    "Mở Cổng / Kiểm Tra Key & Thư Mục": "打开入口 / 检查 Key 与文件夹",
    "🕒 Dùng khi nào:": "🕒 适用时机：",
    "Mỗi lần mở web lần đầu tiên, khi đổi tài khoản Google AI Studio mới hoặc khi vừa quay lại trình duyệt để rà soát nhanh trạng thái Key trước lúc sáng tác.": "每次首次打开网页、更换新的 Google AI Studio 账号，或回到浏览器准备写作前快速核对 Key 状态时。",
    "📋 Các bước thực hiện chuẩn:": "📋 标准操作步骤：",
    "Bấm nút \"Mở Google AI Studio Để Copy API Key Ngay\" để lấy khóa AIza... hoặc AQ... từ tài khoản Google của bạn.": "点击“立即打开 Google AI Studio 复制 API Key”按钮，从您的 Google 账号获取 AIza... 或 AQ... 密钥。",
    "Dán khóa vào ô nhập liệu; hệ thống tự động gọi mô hình Flash-Lite nhẹ nhất để kiểm tra sống-chết mà không tốn đáng kể hạn mức.": "将密钥粘贴到输入框；系统将自动调用最轻量的 Flash-Lite 模型进行连通性检测，几乎不消耗额度。",
    "Nếu trước đó bạn đã lưu Key và Thư mục, Cổng kết nối vẫn hiện lại ngắn gọn để bạn rà soát và bấm nút xanh lá vào Studio.": "如果您之前已保存 Key 和文件夹，连接入口仍会简洁展示以便您核对，点击绿色按钮即可进入 Studio。",
    "💡 Mẹo tác giả:": "💡 作者小贴士：",
    "Bạn có thể mở lại Cổng kết nối bất kỳ lúc nào ngay trong Tab 6 bằng nút \"Kiểm Tra / Đổi Key & Thư Mục Kết Nối\" để thay Key mới mà không cần tải lại trang.": "您可以随时在 Tab 6 点击“检查 / 更换 Key 与关联文件夹”重新打开连接入口，无需刷新页面即可更换新 Key。",
    "▸ Chọn & Ghi Nhớ Thư Mục Làm Việc Trên Ổ Cứng (Hỗ Trợ Cả PC Lẫn Điện Thoại)": "▸ 选择并记忆本地硬盘工作文件夹（同时支持电脑与手机）",
