    "Đi tới nút Zen Mode Tab 1": "前往 Tab 1 Zen Mode 按钮",
    "▸ Hệ Thống Undo / Redo Đa Tầng & Nháp Nhanh (Scratchpad)": "▸ 多层撤销 / 重做系统与随手便签 (Scratchpad)",
