    "Đi tới Tab 2 (+ Chương Mới)": "前往 Tab 2（+ 新建章节）",
    "▸ Nạp Bản Thảo Hàng Loạt Từ Máy (.DOCX, .PDF, .TXT, .MD) & Tự Động Tách Chương": "▸ 从本地批量导入草稿（.DOCX、.PDF、.TXT、.MD）并自动拆章",
    "Mở khay Lọc & Nạp File Tab 2": "打开 Tab 2 筛选与文件导入栏",
    "▸ Tra Cứu Ký Ức Cũ Bằng Thuật Toán BM25 (0 Token API — Chạy Tức Thì Tại Chỗ)": "▸ 使用 BM25 算法检索历史记忆（0 Token API — 本地即时运行）",
    "Mở Tra Cứu BM25 tại Tab 2": "在 Tab 2 打开 BM25 检索",
    "▸ Chuẩn Hóa Câu Thoại Nhanh & Công Cụ Biên Tập Trong Khay Thu Gọn Tab 2": "▸ Tab 2 折叠栏中的快速对话规范与编辑工具",
    "Đi tới nút Chuẩn Hóa Thoại Tab 2": "前往 Tab 2 规范对话按钮",
    "▸ 5 Chế Độ Viết Tiểu Thuyết Chuyên Biệt (Từ Viết Nháp, Tham Mưu Đến Vẽ Sơ Đồ)": "▸ 5 种专业小说创作模式（涵盖正文起草、剧情参谋到图表绘制）",
    "Mở Trung Tâm AI 5 Chế Độ Tab 3": "打开 Tab 3 五模式 AI 中心",
    "▾ Đủ Hệ Gemini 4 (Hydrogen / Argon / Carbon) + Pro / Flash & Tư Duy Thấp / TB / Cao / XHIGH": "▾ 完整 Gemini 4 系列 (Hydrogen / Argon / Carbon) + Pro / Flash 与 低/中/高/XHIGH 思考深度",
    "Mở Chọn Mô Hình & Tư Duy Tab 3": "打开 Tab 3 模型与思考深度选择",
    "Khi cần viết chương sâu sắc hoặc kiểm toán logic nhiều tầng (chọn Gemini 4 Hydrogen + Tư duy Cao/XHIGH), viết đại tự sự (Argon 4), hoặc nháp nhanh tiết kiệm quota (Flash / Flash-Lite).": "当需要撰写深度章节或进行多层逻辑审计时（选 Gemini 4 Hydrogen + 高/XHIGH 思考）、撰写宏大叙事时（Argon 4），或节省额度快速起草时（Flash / Flash-Lite）。",
    "Trong Trung tâm điều khiển AI Tab 3, Cổng Bước 2, Chế độ 5, Tab 4 Bible hoặc Trợ lý Viên Bi Số 8, chọn mô hình mong muốn ở danh sách \"Mô hình Gemini\".": "在 Tab 3 AI 控制中心、第 2 步入口、模式 5、Tab 4 设定集或 8 号球助手中，于“Gemini 模型”列表中选择目标模型。",
    "Chọn tiếp mức \"Tư duy: Thấp / Trung bình / Cao / XHIGH\" để điều chỉnh chiều sâu suy luận của AI đồng bộ tới API Key.": "接着选择“思考深度：低 / 中 / 高 / XHIGH”，将 AI 推理深度同步应用到您的 API Key。",
    "Nếu mô hình Pro hoặc Argon-4 bị giới hạn endpoint trên Key miễn phí, hộp thoại dự phòng hiện sẵn link copy câu lệnh & link mở thẳng \"Gemini của bạn\".": "如果 Pro 或 Argon-4 在免费 Key 上受限于端点，备用弹窗会直接提供复制指令链接与一键打开“您的 Gemini”的链接。",
    "Khi mở hộp thoại dự phòng Pro/Argon-4, chỉ cần bấm chữ \"câu lệnh dưới đây\" là toàn văn Prompt Tổng Hợp tự động chép gọn vào clipboard cho bạn dán sang Gemini Web.": "当打开 Pro/Argon-4 备用弹窗时，只需点击“下方指令”文字，完整综合提示词就会自动复制到剪贴板供您粘贴到 Gemini 网页版。",
    "▸ Đồng Hồ Hạn Mức Ngắn Hạn (5 Giờ) & Dài Hạn (Tuần) Kèm Link Gemini Account Live": "▸ 短期（5 小时）与长期（每周）额度仪表盘及实时 Gemini 账号链接",
    "Xem Hạn Mức 5h & Tuần Ở Tab 3": "在 Tab 3 查看 5h 与每周额度",
    "▸ Quy Trình 2 Bước: Copy Thẳng Story Bible Vào Prompt Tổng Hợp -> Chạy Chính Thức": "▸ 两步流程：将设定集直接复制进综合提示词 -> 正式运行",
    "Đi tới Khung Lệnh 2 Bước Tab 3": "前往 Tab 3 两步指令面板",
    "▸ Nhấn Enter Để Chạy Lệnh Nhanh Kèm Hộp Thoại Xác Nhận An Toàn (Có Tick Không Nhắc Lại)": "▸ 按 Enter 快速运行指令并附带安全确认弹窗（支持勾选不再提醒）",
    "Thử Phím Enter Trong Khung Lệnh Tab 3": "试用 Tab 3 指令框中的 Enter 键",
    "▸ Thông Báo Kết Quả Xong & Tự Hiện Đầu Ra Mới Nhất Ngay Trong Khung Chữ Tab 3": "▸ 完成通知并直接在 Tab 3 文本框内自动展示最新输出结果",
    "Đi tới Cửa Sổ Đầu Ra Tab 3": "前往 Tab 3 输出窗口",
    "▸ Chèn Nối Tiếp, Thay Thế, Sao Chép & Đưa Thẳng Kết Quả Vào Story Bible": "▸ 接续插入、替换、复制并直接将结果存入设定集",
    "Đi tới nút Chèn Nối Tiếp Tab 3": "前往 Tab 3 接续插入按钮",
    "▸ Chế Độ 5: Vẽ Biểu Đồ Cốt Truyện & Niên Biểu Dựa Theo Story Bible (Siêu Nhẹ, Chính Xác)": "▸ 模式 5：基于设定集绘制剧情与年表图（超轻量、精准）",
    "Đi tới Trạm Vẽ Biểu Đồ Mode 5": "前往 Mode 5 绘图站",
    "▸ Chèn Mốc Chuyển Phân Cảnh & Đổi Góc Nhìn (POV Switch Builder)": "▸ 插入场景切换与视角转换构建器 (POV Switch Builder)",
    "Mở Bộ Tạo Mốc Chuyển Cảnh": "打开转场标记生成器",
    "▸ ⚡ Bóc Tách Tự Động Nhân Vật, Bí Mật & Phục Bút Bằng Gemini Flash": "▸ ⚡ 使用 Gemini Flash 自动提取角色、秘密与伏笔",
    "Đi tới nút Đồng Bộ Gemini Flash Tab 4": "前往 Tab 4 Gemini Flash 同步按钮",
    "▸ Cập Nhật Story Bible Lũy Tiến Toàn Mạch (Từ Chương 1 Tới Chương Mới Duyệt Cuối)": "▸ 全脉络累进更新设定集（从第 1 章到最新审定章节）",
    "Xem Khung Story Bible Chính Thức Tab 4": "查看 Tab 4 正式设定集框",
    "▾ Cẩm Nang Chống Quên Cho Truyện Dài Hàng Trăm Chương Cùng Google NotebookLM": "▾ 搭配 Google NotebookLM 的百章长篇防遗忘指南",
    "Đi tới Cẩm Nang NotebookLM Tab 4": "前往 Tab 4 NotebookLM 指南",
    "Khi tác phẩm của bạn đã vượt 15-30 chương trở lên hoặc khi bạn muốn tái tổng hợp một bộ Story Bible siêu chi tiết không sót bất kỳ manh mối nào từ đầu truyện.": "当您的作品已超过 15–30 章，或希望重新梳理一份不遗漏开篇任何线索的超详尽设定集时。",
    "Vào Tab 4, nhìn thẻ nổi bật \"Mẹo Giữ Ký Ức Cho Truyện Dài Hàng Trăm Chương Với NotebookLM\".": "进入 Tab 4，找到醒目卡片“百章长篇使用 NotebookLM 保持记忆的技巧”。",
    "Bấm nút \"1. Tải PDF Gộp Toàn Bộ Chương\" để đóng gói tất cả từ Chương 1 -> Chương cuối thành 1 bản PDF.": "点击“1. 下载全部章节合并 PDF”按钮，将第 1 章 -> 最后一章打包为 1 份 PDF。",
