    "Xem hướng dẫn từng bước": "查看分步指南",
    "Chỉ đạo AI: Sử dụng kỹ thuật Match Cut điện ảnh: Kết thúc cảnh trước bằng hình ảnh một vật thể (ví dụ: tàn thuốc đỏ rực, giọt nước mưa, vòng xoáy tách cà phê) và mở đầu cảnh này bằng một hình ảnh có hình dáng/chuyển động tương tự ở không gian mới. Ví dụ văn phong: * * * Vệt khói trắng mảnh mai từ đầu điếu thuốc vừa tắt ngấm trong căn phòng thẩm vấn dường như nối dài ra, hòa vào màn sương mù dày đặc đang bao phủ lấy bến cảng phía Đông lúc hai giờ sáng.": "AI 指导：运用电影级 Match Cut（匹配剪辑）技巧：以上一场景中的某个物体画面收尾（如暗红烟灰、雨滴、咖啡杯旋涡），并在新场景开头以形态或动态相似的画面承接。文风示例：* * * 审讯室里刚刚掐灭的烟头升起一缕纤细白烟，仿佛无限延伸出去，融入凌晨两点笼罩东码头的浓雾之中。",
