    "Viết tiếp ngay sau tiếng chuông ở cuối Chương 3: Trần Minh Khôi và Lệ Băng bước lên sàn gỗ gác chuông tối đen, phát hiện cuộn băng ghi âm nằm sau quả lắc đồng. Giữ đúng xưng hô Tôi/Anh - Cô, tuyệt đối không dùng các cụm sáo ngữ bị cấm và không để lộ bí mật vết sẹo cổ tay quá sớm.": "紧接第 3 章末尾的钟声续写：Trần Minh Khôi 与 Lệ Băng 踏上漆黑的钟楼木地板，在铜钟摆后方发现一盘录音磁带。保持“我/他 - 她”称谓一致，严禁使用任何违禁套话，切勿过早泄露手腕伤疤的秘密。",
    "Viết một phân đoạn hồi tưởng ngắn (khoảng 300 từ) xen góc nhìn POV ngôi thứ ba theo Trần Minh Khôi khi nhớ về ánh lửa hắt lên mặt kính đồng hồ quả quýt bị vỡ, giữ nguyên bí mật về Giáo sư Hoàng cho chương sau.": "撰写一段简短回忆片段（约 300 字），以 Trần Minh Khôi 的第三人称 POV 视角切入，追忆火光映在碎裂怀表玻璃上的情景，并将关于 Giáo sư Hoàng 的秘密保留至下一章。",
    "✍️ [CHẾ ĐỘ 1 — VIẾT BẢN THẢO CHÍNH THỨC] Nhập diễn biến chương truyện, tâm lý nhân vật, bối cảnh không gian hoặc phân cảnh bạn muốn AI triển khai chi tiết (3.000 - 4.000+ từ) tại đây... Ví dụ gợi ý để viết sâu sắc, không tua nhanh: - Cảnh 1 (Mưa khuya ở sảnh ga): Nhân vật A giữ im lặng khi nhận phong thư nặc danh, miêu tả chậm cảm giác lạnh gáy, mùi nước mưa và ánh đèn vàng hắt lên ngón tay run. - Cảnh 2 (Đối thoại căng thẳng): Cuộc chạm trán với Nhân vật B, dùng lời nói ẩn ý chứ chưa vội lật bài ngửa ngay. - Lưu ý: Hệ thống tự động lồng ghép dàn ý đã phát triển ở Chế độ 2 (nếu có) + Story Bible + Mốc chuyển phân cảnh + Ma trận Ai Biết Gì.": "✍️ [模式 1 — 正式正文起草] 在此输入您希望 AI 深入展开的章节剧情、角色心理、空间氛围或具体桥段（3,000 - 4,000+ 字）... 深度慢写示例建议：- 场景 1（车站大厅深夜雨）：角色 A 收到匿名信件时保持沉默，慢节奏刻画后颈寒意、雨水气息与照在颤抖指尖的暖黄灯光。- 场景 2（紧张对话）：与角色 B 正面交锋，运用含蓄试探而非急于摊牌。- 提示：系统会自动整合模式 2 生成的大纲（如有）+ 设定集 + 转场标记 + 知情矩阵。",
    "✅ Duyệt & Chốt Bản Thảo — Tự Động Cập Nhật Story Bible": "✅ 审定并锁定草稿 — 自动更新设定集",
