    "Ngay khi tờ ảnh cũ rơi xuống mặt bàn, cái tên viết bằng mực đỏ phía sau lại chính là tên của [Nhân vật đáng tin nhất].": "旧照片刚落到桌面上，背面用红墨水写着的名字，竟正是[最值得信赖的角色]的名字。",
    "Tin nhắn / Cuộc gọi nửa đêm": "午夜短信 / 来电",
    "Màn hình điện thoại sáng bừng giữa bóng tối với dòng tin ngắn vỏn vẹn ba chữ: \"Đừng mở cửa.\"": "手机屏幕在黑暗中骤然亮起，上面只有短短几个字：“别开门。”",
    "Sai lệch ký ức / Hiện trường": "记忆与现场偏差",
    "Hắn chắc chắn mình đã khóa trái chiếc ngăn kéo lúc rời phòng — thế nhưng chiếc chìa khóa đồng lúc này lại nằm ngay trên gối.": "他确信自己离开房间时反锁了抽屉——可那把铜钥匙此刻却正静静躺在枕头上。",
    "Câu hỏi bỏ lửng gây sởn gai ốc": "令人毛骨悚然的反问",
    "- Cậu nghĩ suốt ba năm qua... người đang ngồi nói chuyện với cậu mỗi tối thực sự là ai? (Nhân vật B)": "“你以为这三年来……每晚坐在你对面聊天的人，究竟是谁？”（角色 B）",
    "Đếm ngược thời gian gấp": "紧迫倒计时",
    "Đồng hồ trên tháp chuông vừa điểm mười hai tiếng, và đúng lúc ấy toàn bộ đèn hành lang đồng loạt tắt phụt.": "钟楼上的大钟刚刚敲响十二下，就在那一刻，整条走廊的灯光齐刷刷地熄灭了。",
    "Sự phản bội bất ngờ": "突如其来的背叛",
    "Lưỡi dao không dừng lại ở cổ đối phương, mà quay ngược lại kề sát ngay động mạch của chính người vừa giải cứu cô.": "刀锋并没有停在敌人的咽喉前，而是调转方向，紧贴上了刚刚救下她的人的颈动脉。",
