    "Ngón tay cái khẽ miết dọc viền chiếc bật lửa bạc rồi mới chịu lên tiếng.": "他的拇指沿着银色打火机的边缘轻轻摩挲了一会儿，这才开口。",
    "Châm biếm / Lạnh nhạt": "讽刺 / 冷漠",
    "Hắn không nhìn đối phương mà chỉ chăm chú chỉnh lại gấu tay áo.": "他看也不看对方一眼，只顾着专注地整理袖口。",
    "Sốc / Đứng hình": "震惊 / 僵住",
    "Đôi môi khẽ hé nhưng không bật ra âm thanh nào trong suốt hai nhịp thở.": "双唇微张，却足足过了两口呼吸的时间都没能发出半点声音。",
    "Cố giữ bình tĩnh": "强作镇定",
    "Cô hít một hơi thật chậm qua mũi, vai hạ xuống vài milimet như vừa tháo một chiếc mặt nạ.": "她用鼻尖极慢地吸了一口气，肩膀微微下沉几毫米，仿佛刚刚摘下一副面具。",
