    "Bạn nên làm rõ bạn muốn AI viết mấy phân cảnh (Càng chia nhỏ càng tốt), mạch truyện nhanh hay chậm, mỗi phân cảnh bao nhiêu từ... Cơ bản như vậy cộng với cái story bible và cái cốt truyện có AI tư vấn bên cạnh nữa là mình thấy oke rồi đó bạn, mình cũng hay viết tới đó thôi hẹ hẹ": "建议先说明希望 AI 写几个分场（拆得越细越好）、剧情节奏快慢、每个分场大概多少字……基本写清楚这些，再配合旁边的 Story Bible 设定集与 AI 参谋剧情，效果就已经很稳了，我平时也差不多写到这一步而已哈哈。",
