    "✍️ Chế độ 1: Viết Bản Thảo Văn Học Chính Thức (Literary Drafting)": "✍️ 模式 1：正式文学小说正文创作",
    "Sáng tác văn xuôi tiểu thuyết hoàn chỉnh, giàu hình ảnh, cảm xúc chân thực, đối thoại sắc sảo và tuân thủ tuyệt đối Story Bible.": "创作完整细腻的小说散文，富有画面感与真实情感，对白犀利且严格遵守故事圣经设定。",
    "💡 Chế độ 2: Bàn Tròn Ý Tưởng & Thiết Kế Nhánh Cốt Truyện (Plot Brainstorming)": "💡 模式 2：剧情圆桌脑暴与分支走向设计",
    "Đề xuất các phương án phát triển tình tiết đột phá, nút thắt bất ngờ (plot twist), cách gỡ bí kịch bản và phương án thu hồi phục bút.": "提供突破性的剧情发展方案、意外反转节点、卡文破解思路以及伏笔回收方案。",
    "🔍 Chế độ 3: Thanh Tra Logic, Mâu Thuẫn Thời Gian & Ma Trận Ai Biết Gì (Continuity Audit)": "🔍 模式 3：逻辑漏洞、时间线冲突与信息差审查",
    "Rà soát nghiêm ngặt toàn bộ lỗ hổng logic, sai lệch dòng thời gian, nhân vật biết trước thông tin chưa được tiết lộ (OOC / Epistemic Leak) và phục bút bị bỏ quên.": "严格排查所有逻辑漏洞、时间线错位、角色提前知晓未公开机密（OOC / 信息越界泄露）以及遗忘的伏笔。",
    "✨ Chế độ 4: Biên Tập Chuyên Sâu, Gọt Văn Chống Sáo Rỗng & Chuẩn Hóa Thoại (Literary Polish)": "✨ 模式 4：深度文学润色、去套话打磨与对白规范化",
    "Nâng cấp chất lượng văn chương của bản thảo, loại bỏ 100% từ ngữ sáo rỗng (Anti-Cliché), chuẩn hóa định dạng hội thoại và làm giàu nhạc tính tiếng Việt.": "全面提升文稿文学质感，100% 剔除 AI 套话与陈词滥调，统一对话格式并增强行文韵律感。",
    "🎨 Chế độ 5: Vẽ Biểu Đồ Cốt Truyện, Mạng Lưới Nhân Vật & Đối Chiếu Thời Gian (Visual Chronicle)": "🎨 模式 5：绘制剧情图谱、角色关系网与时间线核查",
    "Trích xuất cấu trúc sự kiện, mạng lưới quan hệ nhân vật và dòng thời gian thành sơ đồ trực quan kèm báo cáo đối chiếu xuyên chương.": "将事件结构、角色关系网与时间线提取为可视化图谱，并附带跨章节矛盾核查报告。",
    "🧪 KHUYÊN DÙNG #1 · SIÊU SUY LUẬN XHIGH — CÂN BẰNG TOÀN DIỆN GEMINI 4": "🧪 首选推荐 #1 · XHIGH 超强推理 — Gemini 4 全能均衡版",
    "⚡ Cân bằng Nhanh & Sâu (#1)": "⚡ 速度与深度兼具 (#1)",
    "Lựa chọn ưu tiên số 1 cho cả 5 chế độ: viết chương dài (Chế độ 1), tham mưu cốt truyện (Chế độ 2), kiểm toán mâu thuẫn (Chế độ 3), đánh giá độc giả (Chế độ 4) & vẽ biểu đồ (Chế độ 5).": "五大模式的首选主力：长章正文写作（模式1）、剧情脑暴（模式2）、逻辑审计（模式3）、读者评审（模式4）及图谱绘制（模式5）。",
    "🌟 DÒNG FLASH MƯỢT MÀ & GIÀU CẢM XÚC": "🌟 流畅细腻且富有感染力的 FLASH 系列",
