    "22. YouTube Tự Động Nối Hạ Tầng MP3 Mục 3 Để Phát Nền & Hộp Thoại Ưu Tiên Âm Thanh (Mod 39 & 21)": "22. YouTube 自动接入第 3 项 MP3 后台播放底座与音频优先确认弹窗 (Mod 39 & 21)",
    "MỤC 5 ➔ MỤC 3 MP3 NỀN · ĐỒNG BỘ 2 CHIỀU · XUNG ĐỘT THÔNG MINH": "第 5 项 ➔ 第 3 项 MP3 后台 · 双向同步 · 智能冲突确认",
    "Mặc định phát âm thanh YouTube qua hạ tầng MP3 Mục 3 để thoát trình duyệt/tắt màn hình vẫn nghe ổn định; đồng bộ Tạm dừng/Phát/Tua 2 chiều, tự dừng bài cũ khi đổi video & hỏi xác nhận khi bật MP3 máy.": "默认通过第 3 项 MP3 引擎播放 YouTube 音频，切出浏览器或锁屏也能稳定后台收听；支持暂停/播放/跳转双向实时同步、切换视频自动停止旧音频，以及播放本地 MP3 时的优先确认弹窗。",
    "Chọn bất kỳ video YouTube nào ở Tab 5 Ô #5: khung hình lên ngay đồng thời luồng tiếng tự động nối thẳng sang động cơ MP3 Mục 3 (nghe nền cực ổn định khi chuyển ứng dụng hoặc khóa màn hình).": "在第 5 栏框 #5 选择任意 YouTube 视频：画面立即呈现的同时音频自动直连第 3 项 MP3 引擎，切换应用或锁屏时后台依旧稳定流畅。",
    "Mọi thao tác Dừng / Phát tiếp / Tua ±10s / Kéo thanh thời gian đều đồng bộ 2 chiều theo thời gian thực giữa khung hình YouTube và âm thanh Mục 3; đổi sang video khác sẽ tự tắt tiếng video cũ.": "所有暂停 / 继续 / 快进退 ±10 秒 / 拖动进度条操作都会在 YouTube 画面与第 3 项音频之间实时双向同步；切换至新视频时自动关闭旧视频声音。",
    "Nếu bạn đang mở video YouTube mà bấm nghe một bản nhạc MP3 riêng trên máy tại Mục 3, hộp thoại sẽ hỏi xác nhận có tắt YouTube để chuyển sang nghe bản nhạc đó hay không.": "若正在观看 YouTube 视频时您在第 3 项点击播放设备上的本地 MP3 音乐，弹窗会询问是否停掉 YouTube 并切换至本地音乐。",
    "23. Tự Động Lưu 3 Tầng Mỗi 2 Giây & Khi Đổi Trạng Thái: Văn Bản, Gấp/Mở Mục, Nhạc & Tab": "23. 每 2 秒及状态变更时 3 层自动保存：文字增删、折叠状态、音视频与标签位置",
    "TỰ LƯU MỖI 2 GIÂY · LƯU GẤP/MỞ KHỐI · LƯU TAB & VỊ TRÍ CUỘN": "每 2 秒自动保存 · 记忆面板折叠 · 恢复标签与滚动位置",
    "Mọi thay đổi như gõ/xóa chữ, thu gọn hay mở rộng bảng, dừng/tắt YouTube hay MP3, chọn ngôn ngữ/cỡ chữ và vị trí Tab cuối đều tự lưu sau tối đa 2 giây & lúc rời trang.": "无论是输入或删除正文、折叠或展开功能块、停止/关闭 YouTube 或 MP3、切换语言/字号，还是离开前的所在标签与滚动位置，均在 2 秒内及离页时自动保存。",
    "Gõ hoặc xóa chữ trong bản thảo Tab 1: bộ tự lưu 3 tầng (IndexedDB + Két sắt + Thư mục máy tính) cập nhật tự động sau 2 giây và lưu ngay trước khi đóng tab.": "在第 1 栏正文输入或删改文字：3 层自动保存（IndexedDB + 紧急保险箱 + 本地文件夹）每 2 秒自动更新并在关闭标签前立即写入。",
    "Mọi thao tác Thu gọn / Mở rộng các bảng chức năng ở Tab 1, 2, 5, 6 đều được ghi nhớ y nguyên cho lần mở lại kế tiếp.": "第 1、2、5、6 栏中各功能面板的折叠或展开状态都会原样记住，下次打开页面时自动恢复。",
    "Trạng thái đang phát hoặc đã tắt Video YouTube / Nhạc MP3, cũng như Tab đang mở & vị trí cuộn cuối cùng trước khi rời trang đều được khôi phục chính xác.": "YouTube 视频 / MP3 音乐的播放与关闭状态，以及离开网页前的当前标签与滚动位置都会精准恢复。",
    "24. Cổng Khởi Đầu Tinh Gọn 2 Bước, Cuộn Mượt PC/Mobile & Bảng Thông Báo Từ Google Sheet (Mod 34)": "24. 精简 2 步入门网关、PC/移动端顺滑滚动及 Google Sheet 公告弹窗 (Mod 34)",
    "CỔNG VÀO GỌN SẠCH · CUỘN MƯỢT PC/MOBILE · POPUP THÔNG BÁO GOOGLE SHEET": "精简入口 · PC/手机流畅滚动 · Google Sheet 定时公告弹窗",
    "Rút gọn nút \"Mở Google Studio lấy mã\", lược bỏ phần chọn thư mục thừa, cuộn trọn từ trên xuống dưới trên laptop & điện thoại cùng popup thông báo từ Google Sheet sau khi vào.": "精简“打开 Google Studio 获取密钥”按钮并去除冗余文件夹控件，支持电脑与手机从头顺滑滚至底部，入室后按设定时段弹出 Google Sheet 系统公告。",
    "Tại Cổng Kết Nối trên cả Laptop và Điện thoại, thanh cuộn mượt tới tận đáy để nhập API Key (\"Mở Google Studio lấy mã\") và bấm chọn Thư mục làm việc một bước duy nhất.": "在电脑和手机的入门网关界面中，均可顺畅向下滚动到底部，通过“打开 Google Studio 获取密钥”填入 API Key 并一步选定工作文件夹。",
    "Các nút điều khiển YouTube được tối ưu chống rung giật/nháy sáng khi đang chạy hay đồng bộ.": "全面消除 YouTube 播放、暂停与快进退按钮在运行或同步时的闪烁抖动。",
    "Sau khi vào trang (kể cả Chế Độ Khách hay Chế Độ Đầy Đủ), bảng Thông Báo Bảo Trì / Tin Nhắn Admin từ Google Sheet tự động bật đúng lịch hẹn giờ & thời lượng quy định.": "进入页面后（无论访客模式还是完整模式），来自 Google Sheet 后台的维护与管理员定时公告会按预约时段与持续时长自动弹窗展示。",
    "25. Giao Diện Mobile Không Cắt Đỉnh & Rạp Video Toàn Màn Hình Tương Thích Cả Mobile/Desktop": "25. 手机端零顶部裁切修复 & 兼容手机/电脑全屏的教学视频影院",
    "MOBILE KHÔNG MẤT ĐỈNH · POPUP AN TOÀN · FULLSCREEN VIDEO MOB/PC": "手机顶部锁定不裁切 · 弹窗防遮挡 · 跨端全屏视频影院",
    "Cố định chiều cao thực VisualViewport giúp thanh trên cùng & mọi popup không bao giờ bị mất mép trên khi bật bàn phím hay thu phóng chữ; rạp Video Hướng Dẫn Tab 6 phóng to vừa khít cả điện thoại dọc/ngang và máy tính!": "锁定真实 VisualViewport 视口高度，弹出键盘或放大系统字号时顶部栏与弹窗顶部绝不丢失；第 6 栏教学影院全屏可完美适配竖屏手机、横屏手机与电脑屏幕！",
    "Trên điện thoại Android/iOS (Brave, Chrome, Safari), thanh Header đỉnh & phần trên các Tab 1–6 luôn hiển thị trọn vẹn, tuyệt đối không bị tụt hay cắt mất phần trên khi đổi Tab hoặc mở bàn phím.": "在 Android/iOS（Brave、Chrome、Safari）浏览器中，第 1–6 栏顶部 Header 与上方按钮始终完整可见并可正常上下滚动，绝不会切掉顶部。",
    "Tất cả cửa sổ popup, hộp Mở to / Thu nhỏ AI, Crop video & Lịch sử đều cuộn mượt từ đỉnh xuống đáy, không bao giờ che khuất nút \"✕ Đóng\".": "所有弹窗、最大化 AI 命令台、背景裁剪窗口与版本预览都能从顶部顺畅滚动到底部，绝不遮挡“✕ 关闭”按钮。",
    "Ngay trong Rạp Video Hướng Dẫn Tab 6 này, nút \"⛶ Xem toàn màn hình\" tự căn tỷ lệ 16:9 khít khung trên cả Điện thoại dọc, Điện thoại ngang lẫn Desktop kèm đầy đủ phụ đề & thanh tua phía dưới!": "就在第 6 栏本教学视频影院中，点击“⛶ 全屏观看”会在竖屏手机、横屏手机和桌面端均自动精准适配 16:9 画面，并在下方完整显示双语字幕与进度条！",
    "YouTube Mục 5 Tự Nối Hạ Tầng MP3 Mục 3": "第 5 项 YouTube 自动接入第 3 项 MP3 底座",
