    "🇻🇳 Mỗi khi chọn video YouTube ở Mục 5, khung hình phát ngay đồng thời âm thanh tự động nối sang bộ máy MP3 Mục 3 để chạy nền siêu ổn định ngay cả khi bạn thoát ra ứng dụng khác!": "🇻🇳 在第 5 项选定任意 YouTube 视频后，画面立即开播且音频自动交由第 3 项 MP3 引擎接管，即使切出浏览器去其他应用也能稳定后台播放！",
    "Đồng Bộ 2 Chiều & Chuyển Video Mượt": "双向实时同步与平滑换片",
    "Mọi thao tác Dừng, Phát tiếp, Tua nhanh hay tốc độ phát giữa YouTube và Mục 3 luôn khớp từng giây; chuyển qua video mới sẽ tự động tắt hẳn âm thanh của video cũ.": "YouTube 画面与第 3 项之间在暂停、继续、快进退和倍速上秒级双向同步；切换到新视频时自动彻底关闭旧视频音频。",
    "🇻🇳 Mọi thao tác Dừng, Phát tiếp, Tua nhanh hay tốc độ phát giữa YouTube và Mục 3 luôn khớp từng giây; chuyển qua video mới sẽ tự động tắt hẳn âm thanh của video cũ.": "🇻🇳 YouTube 画面与第 3 项之间在暂停、继续、快进退和倍速上秒级双向同步；切换到新视频时自动彻底关闭旧视频音频。",
