    "🇻🇳 Khi đang xem YouTube mà bạn mở thêm file MP3 cá nhân trên máy tại Mục 3, popup thông minh sẽ hỏi xác nhận có dừng video YouTube để nhường cho bản nhạc riêng không!": "🇻🇳 正在看 YouTube 时若您在第 3 项播放本地 MP3 曲目，系统会弹窗确认是否停止当前 YouTube 视频以优先播放本地音乐！",
    "Tự Lưu 3 Tầng Mỗi 2 Giây & Khi Sửa Chữ": "每 2 秒及删改文字 3 层自动保存",
    "Từ lúc bạn gõ thêm câu mới hay xóa bớt chữ trong bản thảo, cơ chế tự lưu 3 tầng tự động đồng bộ về IndexedDB, Két sắt khẩn cấp và Thư mục máy trong vòng 2 giây.": "每当您在正文中增写或删除文字，3 层自动保存引擎会在 2 秒内自动同步至 IndexedDB、紧急保险箱和本地文件夹。",
    "🇻🇳 Từ lúc bạn gõ thêm câu mới hay xóa bớt chữ trong bản thảo, cơ chế tự lưu 3 tầng tự động đồng bộ về IndexedDB, Két sắt khẩn cấp và Thư mục máy trong vòng 2 giây.": "🇻🇳 每当您在正文中增写或删除文字，3 层自动保存引擎会在 2 秒内自动同步至 IndexedDB、紧急保险箱和本地文件夹。",
