    "🇻🇳 Mọi lựa chọn thu gọn hoặc mở rộng của các thanh công cụ, khung Tab 5 hay khối xếp gọn ở Tab 6 đều được lưu tức thì để lần sau mở web lên giữ đúng bố cục bạn thích.": "🇻🇳 各工具栏、第 5 栏面板以及第 6 栏手风琴模块的收起或展开状态都会即时保存，下次访问依然保持您习惯的布局。",
