    "Mục 5 YouTube tự động chạy nền qua hạ tầng Mục 3 MP3 (Mod 39 & Mod 21): Hiện video ngay khi chọn, đồng bộ 2 chiều Phát/Dừng/Tua, tự ngắt tiếng bài cũ khi đổi video và hỏi xác nhận khi bật MP3 máy lúc YouTube đang chạy.": "第 5 项 YouTube 通过第 3 项 MP3 底座自动后台运行 (Mod 39 & Mod 21)：选片即现画面、播放/暂停/跳转双向同步、切视频自动停旧音及本地 MP3 覆盖前弹窗确认。",
    "Tự động lưu 3 tầng mỗi 2 giây & mọi đổi trạng thái (Mod 09/29/36): Lưu đủ từ gõ/xóa chữ, thu gọn/mở rộng các khối, tắt nhạc/video, cỡ chữ, ngôn ngữ, đồng hồ & vị trí Tab/cuộn cuối trước khi thoát.": "每 2 秒及任何状态改动 3 层自动保存 (Mod 09/29/36)：覆盖正文增删、各面板折叠与展开、音视频停止、字号语言时钟以及离页前所在标签与滚动位置。",
