    "Kết quả viết bản thảo chính thức (Chế độ 1) sẽ hiển thị tại đây.\n• Bạn có thể chỉnh sửa trực tiếp văn bản ngay trong khung này.\n• Bấm \"📥 Chèn nối tiếp\" hoặc \"🔄 Thay thế\" trên thanh trên cùng để đưa vào Bản thảo Chính ở Tab 1 (kèm màu đánh dấu AI để bạn duyệt).": "正式正文草稿结果（模式 1）将显示在此处。\n• 您可以直接在此框中编辑文本。\n• 点击顶部的“📥 追加到正文末尾”或“🔄 替换当前正文”将其同步至 Tab 1（附带 AI 高亮标记供审核）。",
    "Các phương án phát triển cốt truyện, gợi ý nút thắt (Plot Twist) và hướng gỡ bí (Chế độ 2) sẽ hiển thị tại đây.\n• Bạn có thể bấm \"📚 Lưu vào Bible\" để cất giữ các ý tưởng hay vào Hồ sơ Story Bible tại Tab 4.": "剧情发展方案、反转点（Plot Twist）建议与破局思路（模式 2）将显示在此处。\n• 您可以点击“📚 存入设定集”将好点子保存到 Tab 4 故事圣经中。",
    "Các phương án phát triển cốt truyện, gợi ý nút thắt (Plot Twist) và hướng gỡ bí (Chế độ 2) sẽ hiển thị tại đây. • Bạn có thể bấm \"📚 Lưu vào Bible\" để cất giữ các ý tưởng hay vào Hồ sơ Story Bible tại Tab 4.": "剧情发展方案、反转点（Plot Twist）建议与破局思路（模式 2）将显示在此处。• 您可以点击“📚 存入设定集”将好点子保存到 Tab 4 故事圣经中。",
    "Báo cáo rà soát mâu thuẫn dòng thời gian, kiểm tra Ma trận Ai Biết Gì và phát hiện lỗi tính cách nhân vật (Chế độ 3) sẽ hiển thị tại đây.\n• Giúp bạn đảm bảo toàn bộ các chương khớp nhau 100% trước khi chốt duyệt.": "时间线矛盾排查报告、“谁知道什么”信息矩阵校验与角色性格 OOC 检测结果（模式 3）将显示在此处。\n• 助您在定稿前确保全书所有章节 100% 严丝合缝。",
    "Báo cáo rà soát mâu thuẫn dòng thời gian, kiểm tra Ma trận Ai Biết Gì và phát hiện lỗi tính cách nhân vật (Chế độ 3) sẽ hiển thị tại đây. • Giúp bạn đảm bảo toàn bộ các chương khớp nhau 100% trước khi chốt duyệt.": "时间线矛盾排查报告、“谁知道什么”信息矩阵校验与角色性格 OOC 检测结果（模式 3）将显示在此处。• 助您在定稿前确保全书所有章节 100% 严丝合缝。",
    "Bản thảo sau khi được biên tập chuyên sâu, loại bỏ từ cấm sáo rỗng (Anti-Cliché) và chuẩn hóa hội thoại \"- Câu thoại (Tên nhân vật)\" (Chế độ 4) sẽ hiển thị tại đây.\n• Bạn có thể bấm \"🔄 Thay thế\" hoặc \"📥 Chèn nối tiếp\" để cập nhật sang Tab 1.": "深度润色、去除 AI 陈词滥调（Anti-Cliché）并按“- 对话（角色名）”规范化后的稿件（模式 4）将显示在此处。\n• 您可以点击“🔄 替换当前正文”或“📥 追加到正文末尾”同步到 Tab 1。",
    "Bản thảo sau khi được biên tập chuyên sâu, loại bỏ từ cấm sáo rỗng (Anti-Cliché) và chuẩn hóa hội thoại \"- Câu thoại (Tên nhân vật)\" (Chế độ 4) sẽ hiển thị tại đây. • Bạn có thể bấm \"🔄 Thay thế\" hoặc \"📥 Chèn nối tiếp\" để cập nhật sang Tab 1.": "深度润色、去除 AI 陈词滥调（Anti-Cliché）并按“- 对话（角色名）”规范化后的稿件（模式 4）将显示在此处。• 您可以点击“🔄 替换当前正文”或“📥 追加到正文末尾”同步到 Tab 1。",
