    "— Xem thử mẫu chữ xuất PDF: \"Mưa đêm vẫn rơi đều trên mái hiên cũ, phản chiếu ánh đèn vàng ấm áp...\" (Nhân vật chính)": "— PDF 字体预览：“夜雨依旧均匀地敲打在旧屋檐上，映出温暖的昏黄灯光……”（主角）",
